      mall: { type: "boolean", default: false },
      payment: { type: "string" },
      tax: { type: "string" },
      "voucher-xtra": { type: "string" },
      "order-fee": { type: "string" },
      shipping: { type: "string" },
      returns: { type: "string" },
      other: { type: "string" },
      affiliate: { type: "string" },
      roas: { type: "string" },
      margin: { type: "string" },
      json: { type: "boolean", default: false },
